3	public class DifficultyNpc : Npc
4	{
5		private int cost = 10;
6	
7		private static bool difficultySet;
8	
9		public override void Start()
10		{
11			base.Start();
12			if (GameController.resetHubVars)
13			{
14				difficultySet = false;
15			}
16		}
17	
18		public override bool HandleConditionalInteraction()
19		{
20			if (difficultySet && CurrentDialogIndex < 3)
21			{
22				CurrentDialogIndex = 4;
23				return false;
24			}
25			switch (CurrentDialogIndex)
26			{
27			case 3:
28				if (Player.platWallet.balance >= cost)
29				{
30					Player.platWallet.Withdraw(cost);
31					PoolManager.GetPoolItem<EmoteEmitter>().Emit(EmoteType.Heart, 1, transform.position + Vector3.up * 2.75f);
32					SoundManager.PlayAudio("MenuBuy");
33					SoundManager.PlayAudio((!Globals.RandBool) ? "OldWizard1" : "OldWizard0");
34					CurrentDialogIndex = 4;
35					difficultySet = true;
36					GameController.runModifier.AddMod(new HardRunMod());
37				}
38				break;
39			case 4:
40				playerLeavingDialog = true;
41				return true;
42			}
43			return false;
44		}
45	}
