using System.Collections.Generic;

public class HardRunMod : RunMod
{
	public static string staticID = "HardRunMod";

	private List<Item> removeList;

	public HardRunMod()
	{
		modID = staticID;
	}

	public override void Activate()
	{
		SetHardModeStatus(givenStatus: true);
	}

	public override void Deactivate()
	{
		SetHardModeStatus(givenStatus: false);
	}

	private void SetHardModeStatus(bool givenStatus)
	{
		GameController.startingDifficulty = (givenStatus ? 3 : 0);
		if (givenStatus)
		{
			EnemyGlobalStatManager.useDiffScaling = givenStatus;
		}
	}
}
   - *Четыре телепорта* (создаются, когда комната выхода уже найдена компасом; на время боя скрыты), смещения от центра комнаты выхода: на старт (−3.5; +4) бирюзовый; в магазин реликвий (−6.5; +2) зелёный; в магазин арканов (+6.5; +2) пурпурный; в особую комнату (+3.5; +4) тёмно-красный. В магазин или особую комнату ведёт пара «портал + возвратный». Телепорт требует, чтобы все игроки были «доступны» (не мертвы, не в оглушении); затухание 0.8 с + 0.1 с появления; игроки переносятся на цель −1.5 м по Y, возвратный портал
   - *Состав боя:* по 08, плюс правила локаторов: «идеальный локатор» → только элита без добавок; «локатор выхода» → шанс стихийной замены 100% для всех 6 классов; иначе шанс замены `(1 − доля убитых этажа) × 0.5`.
   - *Закрытие портала:* подойти на расстояние ≤ 2 м, нажать «взаимодействие» (достаточно одного «доступного» игрока). Все игроки ставятся в точку портала, хитбокс отключён, защита от падения; анимация портала, 200 частиц пыли, союзники очищены, игроки на паузе; игроки скрываются, когда анимация дошла до 0.1, переход запускается на 1.0 (нормированное время). Подсказка гаснет при выходе дальше 2 м или смерти; флаг «принудительный выход из триггера» блокирует повторное срабатывание, пока игрок не вы
6. **Итоги этажа.** Между этажами и после босса показывается экран итогов: время этажа, процент исследованной карты, золото и кристаллы этажа. Время заморожено. Кнопка «дальше» блокируется на 1.5 с, срабатывает по отпусканию «подтвердить» любого устройства. После финального босса экран итогов показывается один раз, перед концовкой. Порядок открытия: сначала закрывается меню паузы, затем мир на паузе (масштаб 0), игроки на паузе. Процент карты при отключённой миникарте — «--». Заголовок: для эт�
7. **Формула сложности.** `D = петля × 3 + этап(0…2) + стартовая_добавка`. Стартовая добавка 0, в «трудном забеге» 3. Для финального босса номер этапа = 3. D пересчитывается при каждой загрузке этажа или босса.
8. **Что даёт D.**
   - Значение интерполяции `t = clamp(D × 0.5, 0, 1)`: замахи, паузы, перезарядки врагов и боссов сжимаются от «лёгкого» значения к «жёсткому» (например пауза босса 30→20 с; базовая длительность оглушения босса от удара 0.9→0.7 с, не ниже 0.5 с, затем × множитель).
   - Вариант «легендарный» у врагов открывается при D ≥ 4.
   - Прибавка здоровья врагам (обычный забег): `min(D × 20 − 10, 70)`, на D=0 — минус 10.
   - Множитель кристаллов с этажа: `min(D × 0.25, 1)`.
   - В режиме «масштабирование» (трудный забег, петля) вместо прибавки здоровья включается набор: здоровье `+5 × D` плоско, урон врагов `+3% × D`, перезарядки, замахи и выходы из атаки `−3% × D`, длительность оглушения боссов `−2% × D`; статусный урон не масштабируется.
9. **Трудный забег.** Покупается в хабе за кристаллы один раз за забег: `D` стартует с 3, включается режим «масштабирование». Сбрасывается при возврате в хаб.
10. **Петля.** Вход — не из хаба: после первой победы (флаг «игра пройдена», не в гонке боссов) в комнате перед финальным боссом стоит NPC «ткач петли»; за **25 кристаллов** он запускает петлю (как в оригинале; белая вспышка, затем загрузка первого этажа первого этапа). Порядок: диалог → если кристаллов < 25, ветка отказа; при согласии кристаллы списываются сразу (звук покупки), игроки на паузе; запуск происходит ТОЛЬКО по выходе из диалога: анимации (отдых → песочные часы с искрами 8 с; камера к NPC +3 м по
