public AnimFrameData(string newAnimName, int newTotalFrameCount = 30, int newFPS = 60)
{
animName = newAnimName;
totalFrameCount = newTotalFrameCount;
framesPerSecond = newFPS;
sections = new Dictionary<string, AnimSection>();
orderedSectionNames = null;
}
public AnimFrameData(AnimFrameData newAnimFrameData)
{
sections = new Dictionary<string, AnimSection>();
animName = newAnimFrameData.animName;
totalFrameCount = newAnimFrameData.totalFrameCount;
framesPerSecond = newAnimFrameData.framesPerSecond;
orderedSectionNames = new string[newAnimFrameData.sections.Keys.Count];
foreach (KeyValuePair<string, AnimSection> section in newAnimFrameData.sections)
{
sections[section.Key] = new AnimSection(section.Value);
}
if (newAnimFrameData.firstAnimSection != null)
{
firstAnimSection = sections[newAnimFrameData.firstAnimSection.name];
}
ResortSections();
}
public void Add(AnimSection newSection)
{
if (newSection.startFrame > newSection.endFrame)
{
throw new Exception("Invalid frame range for " + newSection.name + " (" + newSection.startFrame + ", " + newSection.endFrame + ") ");
}
foreach (KeyValuePair<string, AnimSection> section in sections)
{
AnimSection value = section.Value;
if ((newSection.startFrame >= value.startFrame && newSection.startFrame <= value.endFrame) || (newSection.endFrame >= value.startFrame && newSection.endFrame <= value.endFrame))
{
throw new Exception("Overlapping anim timings! " + value.name + " (" + value.startFrame + ", " + value.endFrame + ") " + newSection.name + " (" + newSection.startFrame + ", " + newSection.endFrame + ") ");
}
}
newSection.RecalcNormalizedTime(totalFrameCount);
sections[newSection.name] = newSection;
ResortSections();
}
public void ResortSections()
{
KeyValuePair<string, AnimSection>[] array = sections.OrderBy((KeyValuePair<string, AnimSection> s) => s.Value.startFrame).ToArray();
orderedSectionNames = new string[array.Length];
AnimSection animSection = null;
for (int num = 0; num < array.Length; num++)
{
string key = array[num].Key;
orderedSectionNames[num] = key;
AnimSection animSection2 = sections[key];
animSection2.prevAnimSectionName = string.Empty;
animSection2.nextAnimSectionName = string.Empty;
animSection2.prevAnimSection = null;
animSection2.nextAnimSection = null;
if (animSection != null)
{
animSection2.prevAnimSectionName = animSection.name;
animSection2.prevAnimSection = animSection;
animSection.nextAnimSectionName = key;
animSection.nextAnimSection = animSection2;
}
animSection2.sectionIndex = num;
animSection = animSection2;
if (num == 0)
{
firstAnimSection = animSection2;
}
}
}
public void Remove(string name)
{
sections.Remove(name);
ResortSections();
}
public void Print()
{
Debug.Log(" ---- " + animName + " Frame Data ----");
foreach (KeyValuePair<string, AnimSection> section in sections)
{
AnimSection value = section.Value;
Debug.Log(value.name + ": Frames (" + value.startFrame + ", " + value.endFrame + ") Normalized Times: (" + value.startNormalizedTime + ", " + value.endNormalizedTime + ") Speed: " + value.speed);
}
string text = string.Empty;
for (int i = 0; i < orderedSectionNames.Length; i++)
{
text = text + orderedSectionNames[i] + " -> ";
}
text += " END!";
Debug.Log(text);
Debug.Log(" ------------------------------");
}
